-- 0007_reminders: opt-in NEUTRAL reminders delivered ONLY through a DEMO mock transport (KALINGA, S8-1).
-- Safety model:
--  * Reminders are opt-in per booking request and default to OFF. Opting out clears the channel and destination.
--  * No real phone number or e-mail address is ever stored. The "destination" is an opaque DEMO placeholder token
--    ('demo:' + 16 hex characters) generated by the server; the CHECK below makes any other value impossible.
--  * The outbox holds only the neutral rendered text (no clinic, service, date, reference or health wording), a status,
--    attempt counters and an idempotency key. It never holds results, diagnoses, references or secrets.
--  * 'sent' means "recorded by the MOCK transport", not "delivered to a person".
--  * RLS is enabled with no policy and no grant: kalinga_public and kalinga_staff cannot read these tables directly.

create type reminder_channel as enum ('mock_sms', 'mock_email');
create type reminder_kind as enum ('visit_reminder');
create type reminder_status as enum ('queued', 'sent', 'failed', 'suppressed');

create table reminder_preferences (
  booking_request_id uuid primary key references booking_requests (id) on delete cascade,
  opted_in boolean not null default false,
  channel reminder_channel,
  -- Opaque DEMO placeholder. NEVER a real phone number or e-mail address.
  destination_token text check (destination_token is null or destination_token ~ '^demo:[0-9a-f]{16}$'),
  destination_is_demo boolean not null default true check (destination_is_demo),
  locale text not null default 'en' check (locale in ('en', 'fil')),
  consented_at timestamptz,
  disabled_at timestamptz,
  updated_at timestamptz not null default now(),
  constraint reminder_preferences_opt_in_complete check (
    (opted_in and channel is not null and destination_token is not null and consented_at is not null)
    or (not opted_in and channel is null and destination_token is null)
  )
);

create table reminder_outbox (
  id uuid primary key default gen_random_uuid(),
  booking_request_id uuid not null references booking_requests (id) on delete cascade,
  kind reminder_kind not null default 'visit_reminder',
  channel reminder_channel not null,
  locale text not null default 'en' check (locale in ('en', 'fil')),
  scheduled_for timestamptz not null,
  status reminder_status not null default 'queued',
  attempts integer not null default 0 check (attempts between 0 and 3),
  -- Backoff: a failed attempt that may be retried is not tried again before this instant.
  next_attempt_at timestamptz,
  last_error_code text check (last_error_code is null or last_error_code ~ '^[a-z0-9_]{1,40}$'),
  -- Deterministic per (booking request, kind, channel, visit time): the same reminder can never be queued twice.
  idempotency_key text not null unique check (length(idempotency_key) between 8 and 200),
  -- Neutral text only (see the renderer and its banned-terms tests). Short by design.
  rendered_text text not null check (length(rendered_text) between 1 and 200),
  -- No reminder is sent after this instant (the visit time).
  expires_at timestamptz not null,
  sent_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint reminder_outbox_sent_has_time check ((status = 'sent') = (sent_at is not null))
);
create index reminder_outbox_due_idx on reminder_outbox (status, scheduled_for);
create index reminder_outbox_booking_idx on reminder_outbox (booking_request_id);

alter table reminder_preferences enable row level security;
alter table reminder_outbox enable row level security;

comment on table reminder_preferences is 'Opt-in flag per booking request. destination_token is an opaque DEMO placeholder, never a real contact detail.';
comment on table reminder_outbox is 'MOCK transport outbox. Neutral rendered text only; sent means recorded by the mock transport, not delivered to a person.';
